// Countries for the server form: ISO 3166-1 alpha-2 code + Russian name (from the browser's Intl data).
const CODES = [
  'RU', 'UA', 'BY', 'KZ', 'PL', 'DE', 'FR', 'GB', 'NL', 'US', 'CA', 'FI', 'SE', 'NO', 'DK', 'CZ', 'SK', 'HU', 'RO', 'BG', 'RS', 'HR', 'SI',
